{step==='Brands'&&<BrandManager key={selectedWorkspace} brands={brands} assets={assets} busy={busy} readOnly={workspaces.find(w=>w.id===selectedWorkspace)?.role==='viewer'} onApply={applyBrand} onSave={brand=>void action(async()=>{await api('brands',brand,'PUT');setBrands((await api('brands')).brands);setMessage('Brand kit saved to this workspace.');})}/>}
